17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	
22	import org.springframework.http.HttpHeaders;
23	import org.springframework.http.HttpStatus;
24	import org.springframework.http.ResponseEntity;
25	import org.springframework.samples.petclinic.mapper.OwnerMapper;
26	import org.springframework.samples.petclinic.mapper.PetMapper;
27	import org.springframework.samples.petclinic.mapper.VisitMapper;
28	import org.springframework.samples.petclinic.model.Owner;
29	import org.springframework.samples.petclinic.model.Pet;
30	import org.springframework.samples.petclinic.model.Visit;
31	import org.springframework.samples.petclinic.rest.advice.CityAtCapacityException;
32	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitException;
33	import org.springframework.samples.petclinic.rest.advice.DuplicateHouseholdException;
34	import org.springframework.samples.petclinic.rest.advice.DuplicateTelephoneException;
35	import org.springframework.samples.petclinic.rest.advice.InvalidAddressException;
36	import org.springframework.samples.petclinic.rest.advice.InvalidEmailException;
37	import org.springframework.samples.petclinic.rest.advice.InvalidTelephoneException;
38	import org.springframework.samples.petclinic.rest.api.OwnersApi;
39	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
40	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
41	import org.springframework.samples.petclinic.rest.dto.PetDto;
42	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitDto;
44	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
45	import org.springframework.samples.petclinic.service.ClinicService;
46	import org.springframework.samples.petclinic.util.Households;
47	import org.springframework.security.access.prepost.PreAuthorize;
48	import org.springframework.web.bind.annotation.CrossOrigin;
49	import org.springframework.web.bind.annotation.RequestMapping;
50	import org.springframework.web.bind.annotation.RestController;
51	import org.springframework.web.util.UriComponentsBuilder;
52	
53	import jakarta.transaction.Transactional;
54	
55	/**
56	 * @author Vitaliy Fedoriv
57	 */
58	
59	@RestController
60	@CrossOrigin(exposedHeaders = "errors, content-type")
61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /**
65	     * Dedicated audit logger. On a successful owner create an audit line is emitted here carrying the
66	     * new owner's id, its assigned {@code customerCode}, its {@code registrationDate} and its
67	     * numeric {@code membershipLevel}.
68	     */
69	    private static final org.slf4j.Logger AUDIT = org.slf4j.LoggerFactory.getLogger("AUDIT");
70	
71	    private final ClinicService clinicService;
72	
73	    private final OwnerMapper ownerMapper;
74	
75	    private final PetMapper petMapper;
76	
77	    private final VisitMapper visitMapper;
78	
79	    public OwnerRestControllerV1(ClinicService clinicService,
80	                                 OwnerMapper ownerMapper,
81	                                 PetMapper petMapper,
82	                                 VisitMapper visitMapper) {
83	        this.clinicService = clinicService;
84	        this.ownerMapper = ownerMapper;
85	        this.petMapper = petMapper;
86	        this.visitMapper = visitMapper;
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
92	        Collection<Owner> owners;
93	        if (lastName != null) {
94	            owners = this.clinicService.findOwnerByLastName(lastName);
95	        } else {
96	            owners = this.clinicService.findAllOwners();
97	        }
98	        if (owners.isEmpty()) {
99	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
100	        }
101	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
102	    }
103	
104	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
105	    @Override
106	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
107	        Owner owner = this.clinicService.findOwnerById(ownerId);
108	        if (owner == null) {
109	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
110	        }
111	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
112	    }
113	
114	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
115	    @Override
116	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
117	        HttpHeaders headers = new HttpHeaders();
118	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
119	        owner.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
120	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
121	        if (registrationDate == null) {
122	            registrationDate = java.time.LocalDate.now();
123	        }
124	        registrationDate = toBusinessDay(registrationDate);
125	        owner.setRegistrationDate(registrationDate);
126	        rejectDailyLimitReached(registrationDate);
127	        rejectCityAtCapacity(owner.getCity());
128	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
129	            rejectDuplicateHousehold(owner.getLastName(), owner.getAddress());
130	        }
131	        String telephone = normalizeTelephone(ownerFieldsDto.getTelephone());
132	        rejectDuplicateTelephone(telephone);
133	        owner.setTelephone(telephone);
134	        owner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
135	        owner.setCustomerCode(assignCustomerCode(owner.getCity(), owner.getLastName()));
136	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
137	        owner.setBulkSignupWarning(computeBulkSignupWarning(registrationDate));
138	        owner.setHouseholdSize(countHouseholdMembers(owner.getLastName(), owner.getAddress()) + 1);
139	        this.clinicService.saveOwner(owner);
140	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
141	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={}",
142	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
143	            ownerDto.getMembershipLevel());
144	        headers.setLocation(UriComponentsBuilder.newInstance()
145	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
146	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
147	    }
148	
149	    /**
150	     * The maximum number of owners that may be created in a single day. Creating an owner once this
151	     * many owners already carry today's {@code registrationDate} is rejected.
152	     */
153	    private static final int DAILY_OWNER_LIMIT = 100;
154	
155	    /**
156	     * Rejects creating an owner once {@value #DAILY_OWNER_LIMIT} or more owners already carry the
157	     * given business day as their {@code registrationDate}. The count is keyed by the
158	     * business-day-adjusted registration date of the owner being created (see
159	     * {@link #toBusinessDay}), so all owners falling on the same business day count together. Owners
160	     * with no {@code registrationDate} are ignored.
161	     *
162	     * @param registrationDate the business-day-adjusted registration date of the owner being created
163	     * @throws DailyOwnerLimitException (429 Too Many Requests) if the daily limit is already reached
164	     */
165	    private void rejectDailyLimitReached(java.time.LocalDate registrationDate) {
166	        long count = this.clinicService.findAllOwners().stream()
167	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
168	            .count();
169	        if (count >= DAILY_OWNER_LIMIT) {
170	            throw new DailyOwnerLimitException(registrationDate);
171	        }
172	    }
173	
174	    /**
175	     * The threshold of owners already created on a business day beyond which a bulk-signup warning is
176	     * raised on a new owner. Once strictly more than this many owners already carry the day as their
177	     * {@code registrationDate}, the new owner's {@code bulkSignupWarning} is set to {@code true}.
178	     */
179	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
180	
181	    /**
182	     * Computes the {@code bulkSignupWarning} for an owner being created: {@code true} when more than
183	     * {@value #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been created today, otherwise
184	     * {@code false}. Existing owners are counted the same way the daily-limit rule counts them (see
185	     * {@link #rejectDailyLimitReached}), keyed by the business-day-adjusted registration date, and the
186	     * owner being created is excluded (it has not yet been saved).
187	     *
188	     * @param registrationDate the business-day-adjusted registration date of the owner being created
189	     * @return {@code true} if more than the threshold of owners already carry this business day
190	     */
191	    private boolean computeBulkSignupWarning(java.time.LocalDate registrationDate) {
192	        long count = this.clinicService.findAllOwners().stream()
193	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
194	            .count();
195	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
196	    }
197	
198	    /**
199	     * Rolls a registration date forward onto a business day: a Saturday or Sunday is moved forward to
200	     * the following Monday; a weekday is returned unchanged. This applies to the effective
201	     * registration date whether it was supplied in the request or defaulted to the server date, and
202	     * every value derived from the registration date uses the adjusted result.
203	     *
204	     * @param date the effective registration date
205	     * @return {@code date} itself when it is a weekday, otherwise the following Monday
206	     */
207	    private java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
208	        while (date.getDayOfWeek() == java.time.DayOfWeek.SATURDAY
209	            || date.getDayOfWeek() == java.time.DayOfWeek.SUNDAY) {
210	            date = date.plusDays(1);
211	        }
212	        return date;
213	    }
214	
215	    /**
216	     * The maximum number of owners a single city may contain. Creating an owner in a city that
217	     * already holds this many owners is rejected.
218	     */
219	    private static final int CITY_CAPACITY = 50;
220	
221	    /**
222	     * Rejects creating an owner whose city already contains {@value #CITY_CAPACITY} or more owners.
223	     * Owners are counted per city comparing the city name case-insensitively (a {@code null} city is
224	     * treated as empty), the same way {@link #assignCustomerCode} counts a city's owners.
225	     *
226	     * @param city the city of the owner being created
227	     * @throws CityAtCapacityException (409 Conflict) if the city is already at capacity
228	     */
229	    private void rejectCityAtCapacity(String city) {
230	        String cityValue = city == null ? "" : city;
231	        long count = this.clinicService.findAllOwners().stream()
232	            .filter(existing -> cityValue.equalsIgnoreCase(
233	                existing.getCity() == null ? "" : existing.getCity()))
234	            .count();
235	        if (count >= CITY_CAPACITY) {
236	            throw new CityAtCapacityException(city);
237	        }
238	    }
239	
240	    /**
241	     * Assigns an owner's {@code customerCode} on create, formatted {@code '<CITY3>-<LAST3>-<NNNN>'}
242	     * where CITY3 is the upper-cased first three letters of the city, LAST3 the upper-cased first
243	     * three letters of the last name and NNNN a per-city 4-digit zero-padded sequence equal to one
244	     * more than the number of owners already in that city (e.g. {@code 'SYD-SMI-0007'}).
245	     *
246	     * @param city the owner's city
247	     * @param lastName the owner's last name
248	     * @return the assigned customer code
249	     */
250	    private String assignCustomerCode(String city, String lastName) {
251	        String city3 = prefix3(city);
252	        String last3 = prefix3(lastName);
253	        String cityValue = city == null ? "" : city;
254	        int sequence = (int) this.clinicService.findAllOwners().stream()
255	            .filter(existing -> cityValue.equalsIgnoreCase(
256	                existing.getCity() == null ? "" : existing.getCity()))
257	            .count() + 1;
258	        return String.format("%s-%s-%04d", city3, last3, sequence);
259	    }
260	
261	    /**
262	     * Returns the upper-cased first three letters of the given value, or fewer if the value is
263	     * shorter, treating {@code null} as empty.
264	     */
265	    private String prefix3(String value) {
266	        String name = value == null ? "" : value;
267	        return name.substring(0, Math.min(3, name.length()))
268	            .toUpperCase(java.util.Locale.ROOT);
269	    }
270	
271	    /**
272	     * Counts how many existing owners share the given first and last name, compared
273	     * case-insensitively, at the time this owner is created. The value excludes the owner
274	     * being created (which has not yet been saved) and is stored on the new owner and returned
275	     * as its {@code namesakeCount}.
276	     *
277	     * @param firstName the first name of the owner being created
278	     * @param lastName the last name of the owner being created
279	     * @return the number of existing owners with the same first and last name
280	     */
281	    private int countNamesakes(String firstName, String lastName) {
282	        String first = firstName == null ? "" : firstName;
283	        String last = lastName == null ? "" : lastName;
284	        return (int) this.clinicService.findAllOwners().stream()
285	            .filter(existing -> first.equalsIgnoreCase(existing.getFirstName())
286	                && last.equalsIgnoreCase(existing.getLastName()))
287	            .count();
288	    }
289	
290	    /**
291	     * Counts how many existing owners belong to the same household as the owner being created, i.e.
292	     * share its {@code householdId} (derived by {@link Households#householdId} from the normalized last
293	     * name and address). The value excludes the owner being created (which has not yet been saved), so
294	     * the household's size after this create is this count plus one. It is stored on the new owner.
295	     *
296	     * @param lastName the last name of the owner being created
297	     * @param address the normalized address of the owner being created
298	     * @return the number of existing owners sharing this owner's household
299	     */
300	    private int countHouseholdMembers(String lastName, String address) {
301	        String householdId = Households.householdId(lastName, address);
302	        return (int) this.clinicService.findAllOwners().stream()
303	            .filter(existing -> householdId.equals(
304	                Households.householdId(existing.getLastName(), existing.getAddress())))
305	            .count();
306	    }
307	
308	    /**
309	     * Normalizes an owner's telephone on create into E.164 form. Spaces, dashes and brackets are
310	     * stripped. A leading '+' and its country code are kept as given; otherwise country code '+61' is
311	     * assumed and a single leading '0' is dropped from the national digits. The resulting number must
312	     * have 8 to 15 digits after the '+'. For example {@code "0412 345 678"} becomes
313	     * {@code "+61412345678"}. The E.164 value is stored and returned.
314	     *
315	     * @param telephone the raw telephone as submitted
316	     * @return the normalized E.164 telephone (a '+' followed by 8 to 15 digits)
317	     * @throws InvalidTelephoneException (400 Bad Request) if the value cannot form a valid E.164 number
318	     */
319	    private String normalizeTelephone(String telephone) {
320	        String raw = telephone == null ? "" : telephone.trim();
321	        boolean hasCountryCode = raw.startsWith("+");
322	        String cleaned = raw.replaceAll("[\\s()\\-]", "");
323	        if (hasCountryCode) {
324	            cleaned = cleaned.substring(1);
325	        }
326	        String digits;
327	        if (hasCountryCode) {
328	            digits = cleaned;
329	        } else {
330	            if (cleaned.startsWith("0")) {
331	                cleaned = cleaned.substring(1);
332	            }
333	            digits = "61" + cleaned;
334	        }
335	        if (!digits.matches("[0-9]{8,15}")) {
336	            throw new InvalidTelephoneException(telephone);
337	        }
338	        return "+" + digits;
339	    }
340	
341	    /**
342	     * Syntactic email pattern: a non-empty local part, an '@', a domain with at least one dot and a
343	     * multi-character top-level label. Deliberately lenient about the exact character set while still
344	     * rejecting values that are clearly not addresses (e.g. missing '@').
345	     */
346	    private static final java.util.regex.Pattern EMAIL_PATTERN =
347	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$");
348	
349	    /**
350	     * Normalizes an owner's email. Email is optional: a {@code null} or blank value is left as
351	     * {@code null} (no email). When present it must be a syntactically valid address; the value is
352	     * lower-cased before being stored and returned.
353	     *
354	     * @param email the raw email as submitted, may be {@code null}
355	     * @return the lower-cased email, or {@code null} when none was supplied
356	     * @throws InvalidEmailException (400 Bad Request) if a non-blank value is not a valid address
357	     */
358	    private String normalizeEmail(String email) {
359	        if (email == null || email.isBlank()) {
360	            return null;
361	        }
362	        String trimmed = email.trim();
363	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
364	            throw new InvalidEmailException(email);
365	        }
366	        return trimmed.toLowerCase(java.util.Locale.ROOT);
367	    }
368	
369	    /**
370	     * Common street-type abbreviations expanded to their full word during address normalization.
371	     */
372	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS = java.util.Map.of(
373	        "ST", "STREET",
374	        "RD", "ROAD",
375	        "AVE", "AVENUE");
376	
377	    /**
378	     * Normalizes an owner's address on create. Surrounding whitespace is trimmed and internal runs of
379	     * whitespace collapse to a single space, the value is upper-cased and common street-type
380	     * abbreviations are expanded to their full word ({@code ST} to {@code STREET}, {@code RD} to
381	     * {@code ROAD}, {@code AVE} to {@code AVENUE}). For example {@code "  12  main  st "} becomes
382	     * {@code "12 MAIN STREET"}. The normalized value is stored and returned, and is also the form used
383	     * for every address comparison (household duplicate detection and the shared household id).
384	     *
385	     * @param address the raw address as submitted
386	     * @return the normalized address
387	     * @throws InvalidAddressException (400 Bad Request) if the address is blank after normalization
388	     */
389	    private String normalizeAddress(String address) {
390	        String collapsed = (address == null ? "" : address).trim().replaceAll("\\s+", " ");
391	        if (collapsed.isEmpty()) {
392	            throw new InvalidAddressException(address);
393	        }
394	        String[] tokens = collapsed.toUpperCase(java.util.Locale.ROOT).split(" ");
395	        StringBuilder normalized = new StringBuilder(collapsed.length());
396	        for (int i = 0; i < tokens.length; i++) {
397	            if (i > 0) {
398	                normalized.append(' ');
399	            }
400	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
401	        }
402	        return normalized.toString();
403	    }
404	
405	    /**
406	     * Rejects creating an owner whose E.164 telephone is already used by another owner. Telephones of
407	     * existing owners are normalized to E.164 the same way before comparison, so equivalent numbers
408	     * submitted in different formats (e.g. national {@code "0412 345 678"} and international
409	     * {@code "+61 412 345 678"}) are still treated as duplicates.
410	     *
411	     * @param telephone the E.164 telephone of the owner being created
412	     * @throws DuplicateTelephoneException (409 Conflict) if another owner already uses this telephone
413	     */
414	    private void rejectDuplicateTelephone(String telephone) {
415	        boolean duplicate = this.clinicService.findAllOwners().stream()
416	            .map(Owner::getTelephone)
417	            .filter(existing -> existing != null)
418	            .map(this::toE164OrNull)
419	            .filter(existing -> existing != null)
420	            .anyMatch(telephone::equals);
421	        if (duplicate) {
422	            throw new DuplicateTelephoneException(telephone);
423	        }
424	    }
425	
426	    /**
427	     * Normalizes an existing owner's telephone to E.164 for duplicate comparison, returning
428	     * {@code null} instead of throwing when the stored value cannot form a valid E.164 number.
429	     */
430	    private String toE164OrNull(String telephone) {
431	        try {
432	            return normalizeTelephone(telephone);
433	        } catch (InvalidTelephoneException e) {
434	            return null;
435	        }
436	    }
437	
438	    /**
439	     * Rejects creating an owner who shares a household with an existing owner, i.e. another owner
440	     * already has the same last name and the same address. Last names are compared case-insensitively
441	     * with whitespace collapsed; addresses are compared in their normalized form (see
442	     * {@link #normalizeAddress}, which every owner's stored address already uses), so values that
443	     * differ only in letter case, spacing or a common street-type abbreviation still count as a match.
444	     * This check is skipped when the request sets {@code sharesHousehold} to {@code true}.
445	     *
446	     * @param lastName the last name of the owner being created
447	     * @param address the normalized address of the owner being created
448	     * @throws DuplicateHouseholdException (409 Conflict) if another owner shares this household
449	     */
450	    private void rejectDuplicateHousehold(String lastName, String address) {
451	        String normalizedLastName = Households.normalize(lastName);
452	        String normalizedAddress = Households.normalize(address);
453	        boolean duplicate = this.clinicService.findAllOwners().stream()
454	            .anyMatch(existing ->
455	                Households.normalize(existing.getLastName()).equals(normalizedLastName)
456	                    && Households.normalize(existing.getAddress()).equals(normalizedAddress));
457	        if (duplicate) {
458	            throw new DuplicateHouseholdException(lastName, address);
459	        }
460	    }
461	
462	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
463	    @Override
464	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
465	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
466	        if (currentOwner == null) {
467	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
468	        }
469	        currentOwner.setAddress(ownerFieldsDto.getAddress());
470	        currentOwner.setCity(ownerFieldsDto.getCity());
471	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
472	        currentOwner.setLastName(ownerFieldsDto.getLastName());
473	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
474	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
475	        this.clinicService.saveOwner(currentOwner);
476	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
477	    }
478	
479	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
480	    @Transactional
481	    @Override
482	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
483	        Owner owner = this.clinicService.findOwnerById(ownerId);
484	        if (owner == null) {
485	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
486	        }
487	        this.clinicService.deleteOwner(owner);
488	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
489	    }
490	
491	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
492	    @Override
493	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
494	        Owner owner = this.clinicService.findOwnerById(ownerId);
495	        if (owner == null) {
496	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
497	        }
498	        HttpHeaders headers = new HttpHeaders();
499	        Pet pet = petMapper.toPet(petFieldsDto);
500	        owner.setId(ownerId);
501	        pet.setOwner(owner);
502	        pet.getType().setName(null);
503	        this.clinicService.savePet(pet);
504	        PetDto petDto = petMapper.toPetDto(pet);
505	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
506	            .buildAndExpand(pet.getId()).toUri());
507	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
508	    }
509	
510	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
511	    @Override
512	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
513	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
514	        if (currentOwner != null) {
515	            Pet currentPet = this.clinicService.findPetById(petId);
516	            if (currentPet != null) {
517	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
518	                currentPet.setName(petFieldsDto.getName());
519	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
520	                this.clinicService.savePet(currentPet);
521	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
522	            }
523	        }
524	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
