221	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
222	     */
223	    @ExceptionHandler(DuplicateHouseholdException.class)
224	    @ResponseBody
225	    public ResponseEntity<ProblemDetail> handleDuplicateHouseholdException(DuplicateHouseholdException e, HttpServletRequest request) {
226	        HttpStatus status = HttpStatus.CONFLICT;
227	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
228	        detail.setProperty("errors", List.of("lastName", "address"));
229	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
230	        detail.setProperty("schemaValidationErrors", List.of(
231	            new ValidationMessageDto("Fields 'lastName' and 'address' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
232	                .putAdditionalProperty("field", "lastName")
233	                .putAdditionalProperty("rejectedValue", rejectedValue)
234	                .putAdditionalProperty("defaultMessage", e.getMessage())));
235	        return ResponseEntity.status(status).body(detail);
236	    }
237	
238	    /**
239	     * Handles {@link CityAtCapacityException} thrown when creating an owner whose city already
240	     * contains the maximum number of owners.
241	     *
242	     * @param e The {@link CityAtCapacityException} to be handled
243	     * @param request {@link HttpServletRequest} object referring to the current request.
244	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
245	     */
246	    @ExceptionHandler(CityAtCapacityException.class)
247	    @ResponseBody
248	    public ResponseEntity<ProblemDetail> handleCityAtCapacityException(CityAtCapacityException e, HttpServletRequest request) {
249	        HttpStatus status = HttpStatus.CONFLICT;
250	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
251	        detail.setProperty("errors", List.of("city"));
252	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
253	        detail.setProperty("schemaValidationErrors", List.of(
254	            new ValidationMessageDto("Field 'city' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
255	                .putAdditionalProperty("field", "city")
256	                .putAdditionalProperty("rejectedValue", rejectedValue)
257	                .putAdditionalProperty("defaultMessage", e.getMessage())));
258	        return ResponseEntity.status(status).body(detail);
259	    }
260	
261	    /**
262	     * Handles {@link DailyOwnerLimitException} thrown when creating an owner after the daily limit of
263	     * owner registrations has already been reached.
264	     *
265	     * @param e The {@link DailyOwnerLimitException} to be handled
266	     * @param request {@link HttpServletRequest} object referring to the current request.
267	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
268	     */
269	    @ExceptionHandler(DailyOwnerLimitException.class)
270	    @ResponseBody
271	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitException(DailyOwnerLimitException e, HttpServletRequest request) {
272	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
273	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
274	        detail.setProperty("errors", List.of("registrationDate"));
275	        String rejectedValue = Objects.toString(e.getRejectedValue(), "null");
276	        detail.setProperty("schemaValidationErrors", List.of(
277	            new ValidationMessageDto("Field 'registrationDate' %s (rejected value: %s)".formatted(e.getMessage(), rejectedValue))
278	                .putAdditionalProperty("field", "registrationDate")
279	                .putAdditionalProperty("rejectedValue", rejectedValue)
280	                .putAdditionalProperty("defaultMessage", e.getMessage())));
281	        return ResponseEntity.status(status).body(detail);
282	    }
283	
284	    /**
285	     * Handles exception thrown by Bean Validation on controller methods parameters
286	     *
287	     * @param e The {@link MethodArgumentNotValidException} to be handled
288	     * @param request {@link HttpServletRequest} object referring to the current request.
289	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
290	     */
291	    @ExceptionHandler(MethodArgumentNotValidException.class)
292	    @ResponseBody
293	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
294	        HttpStatus status = HttpStatus.BAD_REQUEST;
295	        BindingErrorsResponse errors = new BindingErrorsResponse();
296	        BindingResult bindingResult = e.getBindingResult();
297	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
298	        if (bindingResult.hasErrors()) {
299	            errors.addAllErrors(bindingResult);
300	            List<String> errorFields = bindingResult.getFieldErrors().stream()
301	                .map(org.springframework.validation.FieldError::getField)
302	                .distinct()
303	                .toList();
304	            detail.setProperty("errors", errorFields);
305	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
306	                .map(fieldError -> {
307	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
308	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
309	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
310	                        fieldError.getField(),
311	                        defaultMessage,
312	                        rejectedValue);
313	                    return new ValidationMessageDto(message)
314	                        .putAdditionalProperty("field", fieldError.getField())
315	                        .putAdditionalProperty("rejectedValue", rejectedValue)
316	                        .putAdditionalProperty("defaultMessage", defaultMessage);
317	                })
318	                .toList();
319	            logger.debug("Validation error at {} {}: {}",
320	                request.getMethod(),
321	                request.getRequestURI(),
322	                bindingResult.getFieldErrors());
323	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
324	            return ResponseEntity.status(status).body(detail);
325	        }
326	        return ResponseEntity.status(status).body(detail);
327	    }
328	
329	}
